import { Mesh, Group, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, DirectionalLight } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: G, Mesh: M, PlaneGeometry: P, Color: C } = ctx.THREE;

  const root = new G();

  // ---- Backdrop gradient plane (full spec background) ----
  const backdropMat = new MeshStandardNodeMaterial();
  const uvNode = uv();
  const gradNode = mix(vec3(new C('#1b1b23')), vec3(new C('#101015')), uvNode.y);
  backdropMat.colorNode = gradNode;
  const backdropGeom = new P(7, 6);
  const backdropMesh = new M(backdropGeom, backdropMat);
  backdropMesh.position.z = -2.5;
  root.add(backdropMesh);

  // ---- Rim light (accent) ----
  const rimLight = new DirectionalLight(new C('#ff2a38'), 0.8);
  rimLight.position.set(-1, -1, 1);
  root.add(rimLight);

  // ---- Machined‑metal rail ----
  const railMat = new MeshStandardNodeMaterial();
  railMat.metalness = 0.5;
  railMat.roughness = 0.55;
  railMat.clearcoat = 0.2;
  railMat.anisotropy = 0.6;
  railMat.colorNode = gradNode; // same vertical gradient as backdrop
  const railGeom = new P(3.6, 0.5);
  const railMesh = new M(railGeom, railMat);
  railMesh.position.z = 0.15;
  root.add(railMesh);

  // ---- Contact‑shadow plane ----
  const shadowMat = new MeshBasicNodeMaterial({ color: new C('#000000'), transparent: true, opacity: 0.35 });
  const shadowGeom = new P(3.6, 0.5);
  const shadowMesh = new M(shadowGeom, shadowMat);
  root.add(shadowMesh);

  // ---- Underline bar for active entry ----
  const underlineGeom = new P(0.28, 0.025);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.emissive = new C('#ff2a38');
  underlineMat.emissiveIntensity = 1.8;
  const underline = new M(underlineGeom, underlineMat);
  underline.position.z = 0.02;
  root.add(underline);

  // ---- Navigation entries ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const spacing = 0.68;
  const startX = -((items.length - 1) * spacing) / 2;

  const entryGroup = new G();
  root.add(entryGroup);

  const timelines = [];

  items.forEach((item, i) => {
    const isActive = item.role === 'nav-active';
    const txtColor = isActive ? '#e8ecf2' : '#a6adba';

    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: 13,
      color: txtColor,
      align: 'center',
      letterSpacingPx: 0.08 * 13
    });

    const cell = new G();
    cell.position.set(startX + i * spacing, 0, 0);
    cell.add(txt);
    cell.userData.handlers = {};

    // Hover (inactive only)
    if (!isActive) {
      cell.userData.handlers.hover = () => {
        const tl = gsap.timeline();
        tl.to(txt.material.color, {
          r: 0.91,
          g: 0.93,
          b: 0.95,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
        timelines.push(tl);
      };
    }

    // Press (all entries)
    cell.userData.handlers.press = () => {
      const tl = gsap.timeline();
      tl.to(cell.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      });
      tl.to(cell.position, {
        z: -0.03,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      });
      timelines.push(tl);
    };

    entryGroup.add(cell);

    // Position underline under active entry
    if (isActive) {
      underline.position.set(cell.position.x, -0.06, 0.02);
    }
  });

  // ---- Mount rise‑in animation ----
  const rise = gsap.timeline();
  rise.from(root.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)'
  });
  timelines.push(rise);

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    railMat.dispose();
    shadowMat.dispose();
    underlineMat.dispose();
    backdropMat.dispose();
    if (rimLight && rimLight.dispose) rimLight.dispose();
    entryGroup.traverse(o => {
      if (o.isMesh && o.material && o.material.dispose) o.material.dispose();
    });
  };

  return root;
}
